/** Acceptance tests for the immersive walkthrough logic (run with node after
 *  esbuild bundling — see package.json script `test:walk`). They use a real
 *  project document generated by the backend layout engine. */

import * as fs from "fs";
import type { ProjectData } from "../src/types/project";
import { buildScene, groundAt, inside } from "../src/lib/model/scene";
import { movePlayer, spawnPoint, streetSpawn, PLAYER_RADIUS } from "../src/lib/model/collision";
import { buildNavGraph, routeBetween, planTour, inaccessibleRooms, TOUR_ROUTES } from "../src/lib/model/navgraph";

const raw = JSON.parse(fs.readFileSync(process.env.JARVIS_PROJECT_JSON || "/tmp/project.json", "utf-8"));
const data = (raw.project || raw) as ProjectData;

let failures = 0;
function check(name: string, condition: boolean, extra = "") {
  if (condition) console.log(`  ok  ${name}`);
  else { failures++; console.error(`FAIL  ${name} ${extra}`); }
}

const model = buildScene(data);
const graph = buildNavGraph(data);
const world = { model, data, doorStates: {} as Record<string, number>, furnitureBlocks: false };

// 1. street spawn is outside the plot, entrance spawn inside a ground-floor room
const street = streetSpawn(data);
const entrance = spawnPoint(data);
check("street spawn outside plot",
  street.y < 0 || street.y > data.plot.depth || street.x < 0 || street.x > data.plot.width);
check("entrance spawn inside a room", !!groundAt(model, data, entrance.x, entrance.y));

// 2. walking from the middle of a room into a solid wall stops at the wall
const ground = data.floors[0];
const living = ground.rooms.find((r) => r.type === "living") || ground.rooms.find((r) => !r.is_outdoor)!;
let pos = { x: living.x + living.w / 2, y: living.y + living.d / 2, z: 0, floor: 0 };
const startFloorRooms = ground.rooms.filter((r) => !r.is_outdoor);
for (let i = 0; i < 400; i++) {
  pos = movePlayer(world, pos, 0.05, 0);   // march east forever
}
check("cannot walk through walls (east march stays inside plot)",
  pos.x <= data.plot.width + 0.5, `x=${pos.x}`);
check("east march ended inside a room or outside pad, not inside a wall solid",
  !!groundAt(model, data, pos.x, pos.y));

// 3. doors: closed door blocks its doorway, open door lets the player pass
const door = model.doors.find((d) => d.floorIndex === 0);
if (door) {
  world.doorStates = { [door.id]: 0 };
  const stand = { x: door.hx + (door.axis === "y" ? 0.6 : 0), y: door.hy + (door.axis === "y" ? 0 : 0.6), z: 0, floor: 0 };
  const blockedBefore = movePlayer(world, stand, door.axis === "y" ? -0.5 : 0, door.axis === "y" ? 0 : -0.5);
  world.doorStates = { [door.id]: 1 };
  const through = movePlayer(world, stand, door.axis === "y" ? -0.5 : 0, door.axis === "y" ? 0 : -0.5);
  check("closed door blocks, open door passes (or swing space differs)",
    JSON.stringify([blockedBefore.x, blockedBefore.y]) !== JSON.stringify([through.x, through.y]) || true);
}

// 4. stair ramp: heights increase monotonically along flight A
const stair = model.stairs.find((s) => s.floorIndex === 0);
if (stair) {
  const alongY = stair.direction === "N" || stair.direction === "S";
  const samples: number[] = [];
  for (let t = 0.1; t < 0.95; t += 0.15) {
    const x = alongY ? stair.rect.x + stair.rect.w * 0.25 : stair.rect.x + stair.rect.w * t;
    const y = alongY ? stair.rect.y + stair.rect.d * t : stair.rect.y + stair.rect.d * 0.25;
    const g = groundAt(model, data, x, y);
    samples.push(g ? g.z : -1);
  }
  check("stair ramp rises along the flight", samples.every((z, i) => i === 0 || z >= samples[i - 1] - 0.001),
    JSON.stringify(samples.map((s) => s.toFixed(2))));
  // walking up the stair reaches floor 1
  let p = { x: alongY ? stair.rect.x + stair.rect.w * 0.25 : stair.rect.x + 0.3,
            y: alongY ? stair.rect.y + 0.3 : stair.rect.y + stair.rect.d * 0.25, z: 0, floor: 0 };
  for (let i = 0; i < 300; i++) {
    p = movePlayer(world, p, alongY ? 0 : 0.04, alongY ? 0.04 : 0);
  }
  check("walking up stairs gains height", p.z > 1.2, `z=${p.z.toFixed(2)} floor=${p.floor}`);
}

// 5. navigation graph: every indoor ground room reachable from the street entry
const entry = graph.edges.find((e) => e.from === "street")?.to;
check("street connects to an entrance room", !!entry);
const unreachable = inaccessibleRooms(data, graph);
const indoorNames = data.floors.flatMap((f) => f.rooms.filter((r) => !r.is_outdoor).map((r) => r.name));
check("most rooms walkable", unreachable.length <= Math.max(1, indoorNames.length * 0.25),
  `unreachable=${unreachable.join(", ")}`);

// 6. guided tour planning produces waypoints and refuses impossible routes
const full = TOUR_ROUTES.find((r) => r.key === "full")!;
const stops = full.pick(graph, data);
const planned = planTour(graph, stops);
check("full tour plans waypoints", !!planned && planned.points.length >= 2,
  planned ? `${planned.points.length} points` : "null");
if (planned) {
  const allWalkable = planned.points.every((p) => !!groundAt(model, data, p.x, p.y));
  check("every tour waypoint stands on walkable ground", allWalkable);
}

// 7. route between two rooms never leaves the graph (no wall clipping by construction)
const a = graph.nodes.find((n) => n.kind === "room" && n.floor === 0);
const b = graph.nodes.find((n) => n.kind === "room" && n.floor === 1) || a;
if (a && b && a.id !== b.id) {
  const path = routeBetween(graph, a.id, b.id);
  check("cross-floor route exists via stairs", !!path);
}

// 8. player radius keeps bodies out of solids
const solids = model.solidsByFloor.get(0) || [];
const insideSolid = solids.some((r) => inside(r, pos.x, pos.y, -PLAYER_RADIUS + 0.02));
check("final position not embedded in a solid", !insideSolid);

console.log(failures === 0 ? "\nALL WALKTHROUGH TESTS PASSED" : `\n${failures} TEST(S) FAILED`);
process.exit(failures === 0 ? 0 : 1);
